import React, { useState, useEffect } from 'react';
import api from '../../services/api';
import { useAuth } from '../../context/AuthContext';

const CheckInOut = () => {
    const { user } = useAuth();
    const [attendance, setAttendance] = useState(null);
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        checkTodayStatus();
    }, []);

    const checkTodayStatus = async () => {
        try {
            const today = new Date().toISOString().split('T')[0];
            const response = await api.get(`/attendance/today/${user?.EmployeeID}`);
            setAttendance(response.data.data);
        } catch (error) {
            console.error('Error checking attendance:', error);
        }
    };

    const handleCheckIn = async () => {
        setLoading(true);
        try {
            await api.post('/attendance/checkin', { employeeId: user.EmployeeID });
            await checkTodayStatus();
            alert('Check-in successful!');
        } catch (error) {
            alert(error.response?.data?.message || 'Check-in failed');
        } finally {
            setLoading(false);
        }
    };

    const handleCheckOut = async () => {
        setLoading(true);
        try {
            await api.post('/attendance/checkout', { employeeId: user.EmployeeID });
            await checkTodayStatus();
            alert('Check-out successful!');
        } catch (error) {
            alert(error.response?.data?.message || 'Check-out failed');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="container mt-4">
            <div className="card">
                <div className="card-header">
                    <h3>Attendance System</h3>
                </div>
                <div className="card-body text-center">
                    <h4>Welcome, {user?.FirstName} {user?.LastName}</h4>
                    <p className="text-muted">{new Date().toLocaleString()}</p>
                    
                    {!attendance ? (
                        <button 
                            className="btn btn-success btn-lg"
                            onClick={handleCheckIn}
                            disabled={loading}
                        >
                            {loading ? 'Processing...' : 'Check In'}
                        </button>
                    ) : !attendance.CheckOutTime ? (
                        <button 
                            className="btn btn-danger btn-lg"
                            onClick={handleCheckOut}
                            disabled={loading}
                        >
                            {loading ? 'Processing...' : 'Check Out'}
                        </button>
                    ) : (
                        <div className="alert alert-info">
                            <h5>Today's Attendance</h5>
                            <p>Check-in: {attendance.CheckInTime}</p>
                            <p>Check-out: {attendance.CheckOutTime}</p>
                            <p>Total Hours: {attendance.TotalHours}</p>
                            <p>Status: {attendance.Status}</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default CheckInOut;
